package main

import "fmt"

type Point struct{ X, Y int }

type Team struct {
	Name    string
	Members []string
}

func main() {
	p := Point{X: 1, Y: 2}
	q := p // copies both fields
	q.X = 10
	fmt.Printf("%v %v\n", p, q)
	fmt.Printf("%+v\n", p)

	var origin Point
	fmt.Printf("%+v\n", origin)
	r := Point{3, 4}
	fmt.Println(r.X + r.Y)

	red := Team{Name: "Red", Members: []string{"Ann", "Ben"}}
	blue := red
	blue.Name = "Blue"
	blue.Members[0] = "Zoe" // same backing array as red.Members
	fmt.Printf("%+v\n", red)
	fmt.Printf("%+v\n", blue)
}

