package main

import "fmt"

type Pair struct {
	Name  string
	Score int
}

type Box struct {
	Label string
	Items []string
}

func main() {
	a := Pair{Name: "Kim", Score: 70}
	b := a
	b.Score = 85
	fmt.Printf("%+v\n", a)
	fmt.Printf("%+v\n", b)

	var empty Pair
	fmt.Printf("%+v\n", empty)
	c := Pair{"Lee", 60}
	fmt.Println(c.Name)

	crate := Box{Label: "Tools", Items: []string{"saw", "drill"}}
	spare := crate
	spare.Label = "Spare"
	spare.Items[0] = "hammer"
	fmt.Printf("%+v\n", crate)
	fmt.Printf("%+v\n", spare)
}

