func main() {
	visited := map[[2]int]bool{}
	visited[[2]int{0, 0}] = true
	visited[[2]int{0, 1}] = true
	fmt.Println(visited[[2]int{0, 1}], visited[[2]int{2, 2}], len(visited))
	fmt.Println(Point{1, 2} == Point{1, 2}, [2]int{3, 4} == [2]int{4, 3})

	names := map[Point]string{{0, 0}: "start", {5, 5}: "goal"}
	for _, at := range []Point{{5, 5}, {1, 1}} {
		if name, ok := names[at]; ok {
			fmt.Println(name)
		} else {
			fmt.Println("unknown")
		}
	}

	pos := map[string]Point{"ana": {0, 0}}
	p := pos["ana"] // a copy
	p.X += 2
	pos["ana"] = p // store it back
	fmt.Println(pos)
}

