package main

import "fmt"

type Point struct{ X, Y int }

type Stats struct{ Wins, Losses int }

func main() {
	places := map[Point]string{}
	record := map[string]Stats{"ana": {2, 1}}
	places[Point{0, 0}] = "home"
	places[Point{3, 4}] = "school"
	fmt.Printf("Places: %d\n", len(places))
	for _, at := range []Point{{3, 4}, {1, 1}} {
		if label, ok := places[at]; ok {
			fmt.Println(label)
		} else {
			fmt.Println("unknown")
		}
	}

	s := record["ana"]
	s.Wins++
	record["ana"] = s
	fmt.Printf("%+v\n", record)
}
